	'notifications_read' => __( 'همه اعلان‌ها خوانده شدند.', 'revayatiran' ),
	'special_access_requested' => __( 'درخواست دسترسی ویژه ثبت شد و در انتظار بررسی مدیر است.', 'revayatiran' ),
